// T1561b — the sentinel's body: the kit's robot frame, set down in the tunnel.
struct Params {
  travel: f32, // @default 0  Distance travelled along the tunnel, metres.
  offset: vec3f, // @default 0  The robot's place off the tunnel's axis: right, up, ahead (metres).
  roll: f32, // @default 0  Roll about its own heading, radians.
};
// T1561b — the tunnel's centreline (generated by src/projects/sentinel-bot/path.ts).
const PATH_PERIOD: f32 = 960.0;

fn pathAt(z: f32) -> vec3f {
  return vec3f(14.0 * sin(0.0327249235 * z + 0.4) + 5.0 * sin(0.085084801 * z + 1.9), 6.0 * sin(0.0261799388 * z + 2.2) + 2.5 * sin(0.0719948316 * z + 0.7), z);
}

fn pathTangent(z: f32) -> vec3f {
  return normalize(vec3f(0.458148929 * cos(0.0327249235 * z + 0.4) + 0.425424005 * cos(0.085084801 * z + 1.9), 0.157079633 * cos(0.0261799388 * z + 2.2) + 0.179987079 * cos(0.0719948316 * z + 0.7), 1.0));
}

struct Frame {
  origin: vec3f,
  right: vec3f,
  up: vec3f,
  forward: vec3f,
};

fn pathFrame(z: f32) -> Frame {
  var frame: Frame;
  frame.origin = pathAt(z);
  frame.forward = pathTangent(z);
  frame.right = normalize(cross(vec3f(0.0, 1.0, 0.0), frame.forward));
  frame.up = cross(frame.forward, frame.right);
  return frame;
}

// The robot's own frame: on the tunnel's frame at its distance, facing a little way ahead so it
// turns into a bend before it reaches it.
fn robotFrame(travel: f32, offset: vec3f, roll: f32) -> Frame {
  let z = travel + offset.z;
  let tunnel = pathFrame(z);
  var frame: Frame;
  frame.origin = tunnel.origin + tunnel.right * offset.x + tunnel.up * offset.y;
  frame.forward = pathTangent(z + 1.2);
  let right = normalize(cross(vec3f(0.0, 1.0, 0.0), frame.forward));
  let up = cross(frame.forward, right);
  frame.right = right * cos(roll) + up * sin(roll);
  frame.up = up * cos(roll) - right * sin(roll);
  return frame;
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let frame = robotFrame(ctx.params.travel, ctx.params.offset, ctx.params.roll);
  q.position = frame.origin + frame.right * p.position.x + frame.up * p.position.y + frame.forward * p.position.z;
  q.normal = normalize(frame.right * p.normal.x + frame.up * p.normal.y + frame.forward * p.normal.z);
  return q;
}

parameters.source:
struct Params {
  gloss: f32, // @default 0.2  Roughness of the black shell: lower is wetter.
  eyeGlow: f32, // @default 9  Radiance of the eye lenses.
  eyeColor: vec3f, // @default [1, 0.06, 0.03]  Their colour.
  coreGlow: f32, // @default 1.5  Radiance of the red cores.
};

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  let role = s.attr.z;
  if (role > 0.9) {
    // A lens: black glass over a lamp, brightest where it faces the viewer.
    let facing = max(dot(normalize(s.eye - s.world), s.normal), 0.0);
    o.albedo = vec4f(0.01, 0.0, 0.0, 1.0);
    o.roughness = 0.08;
    o.metallic = 0.0;
    o.emissive = p.eyeColor * p.eyeGlow * (0.35 + 0.65 * facing * facing);
  } else if (role > 0.7) {
    o.albedo = vec4f(0.12, 0.004, 0.003, 1.0);
    o.roughness = 0.45;
    o.metallic = 0.0;
    o.emissive = p.eyeColor * p.coreGlow;
  } else if (role > 0.5) {
    o.albedo = vec4f(0.22, 0.012, 0.01, 1.0);
    o.roughness = 0.38;
    o.metallic = 0.6;
  } else if (role > 0.3) {
    o.albedo = vec4f(0.5, 0.36, 0.16, 1.0);
    o.roughness = 0.34;
    o.metallic = 1.0;
  } else if (role > 0.1) {
    o.albedo = vec4f(0.62, 0.64, 0.67, 1.0);
    o.roughness = 0.22;
    o.metallic = 1.0;
  } else {
    o.albedo = vec4f(0.018, 0.019, 0.022, 1.0);
    o.roughness = p.gloss;
    o.metallic = 0.0;
  }
  return o;
}

